/**
 * Jinx Magician + Widow: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Magician
 * Wiki: https://wiki.bloodontheclocktower.com/Widow
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`. Replace the `it.todo` with tests of the rule
 * the jinx imposes, where the engine can check it (for example a setup warning when only one
 * of the two may be in play). Paraphrase, never copy wiki prose.
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong, type Script } from '#lib/core/data/index.ts';
import { committedGameData } from '#lib/core/testing/committed-data.ts';
import { castWith } from '#lib/core/model/fixtures.test-support.ts';
import { nightStepAlerts } from '#lib/core/rules/night-alerts.ts';
import { jinxRulesBetween } from '#lib/core/rules/jinxes.ts';

const scriptOf = (ids: string[]): Script => ({
	meta: { name: 'Jinxed' },
	entries: ids.map((id) => ({ kind: 'official' as const, id }))
});

describe('Magician + Widow jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'magician', 'widow');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('magician')?.name).toBe('Magician');
		expect(data.byId.get('widow')?.name).toBe('Widow');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['magician', 'widow'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['magician'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['widow'])).not.toContain(jinx);
	});

	// Both pages' Related Jinxes: when the Widow sees the Grimoire, the Demon's and the
	// Magician's character tokens come off it. Its step names those players.
	describe('the Demon and Magician tokens come off when the Widow sees the Grimoire', () => {
		const cast = castWith({ script: scriptOf(['widow', 'magician', 'imp', 'chef', 'empath']) });

		it("is data in the Widow's rules", () => {
			expect(jinxRulesBetween('widow', 'magician')).toEqual({
				grimoireHides: ['partner', 'demon']
			});
		});

		it('names the Magician and the Demon at its step', () => {
			const { game, ctx, seats } = cast(['widow', 'magician', 'imp', 'chef', 'empath']);
			const hidden = nightStepAlerts(game, 'widow', ctx.characters).filter(
				(a) => a.kind === 'grimoire-hides'
			);
			expect(hidden.map((a) => [a.seatId, a.source])).toEqual([
				[seats[1], { characterId: 'magician', seatId: seats[1] }],
				[seats[2], { characterId: 'magician', seatId: seats[1] }]
			]);
		});

		it('names nobody when the Magician is not in play', () => {
			const { game, ctx } = cast(['widow', 'chef', 'imp', 'empath', 'monk']);
			expect(
				nightStepAlerts(game, 'widow', ctx.characters).some((a) => a.kind === 'grimoire-hides')
			).toBe(false);
		});
	});
});
